package com.mavric.healthsqlserver;

import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;
import jakarta.servlet.*;
import jakarta.servlet.http.Cookie;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.*;
import org.springframework.security.web.*;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.security.core.userdetails.*;
import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
import org.springframework.security.web.authentication.www.BasicAuthenticationFilter;
import org.springframework.security.web.csrf.CsrfFilter;
import org.springframework.web.context.request.RequestContextHolder;
import com.mavric.health.audit.*;
import com.mavric.health.identity.*;
import com.mavric.health.tenancy.HostFilter;
import com.mavric.health.shared.*;
import static com.mavric.healthsqlserver.SqlServerIdentityConfigurationTest.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;

/** Full Spring Security chain with synthetic servlet and stores, not HTTP, JDBC or runtime grants. */
class SqlServerSecurityConfigurationTest {
    static final String TOKEN="a".repeat(43);
    static class Fixture implements AutoCloseable {
        final Harness h=new Harness();final FilterChainProxy chain;final AtomicBoolean reached=new AtomicBoolean();
        Fixture(){h.refresh();chain=h.context.getBean("springSecurityFilterChain",FilterChainProxy.class);when(h.security.tenantBySlug(any(),eq("clinic"))).thenReturn(Optional.of(Map.of("id",TENANT,"name","Synthetic","slug","clinic","kind","CLINIC","domain","HUMAN","status","ACTIVE","modules",List.of("CORE","PORTAL"))));when(h.security.applicationStatus(any())).thenReturn(Map.of("mode","OPEN","message",""));}
        void session(String tenant,String platformRole){var row=new LinkedHashMap<String,Object>();row.put("userId",ID);row.put("tenantId",tenant);row.put("name","Synthetic");row.put("email","synthetic@example.test");row.put("platformRole",platformRole);row.put("csrfToken","synthetic-csrf");when(h.security.resolveSession(any(),anyString())).thenReturn(Optional.of(row));when(h.security.activeMembership(any(),eq(ID))).thenReturn(Optional.of(Map.of("userId",ID,"status","ACTIVE","roles",List.of("REC"))));}
        MockHttpServletRequest request(String method,String path,String host){var req=new MockHttpServletRequest(h.servlet,method,path);req.setServletPath(path);req.setServerName(host);req.setServerPort(8080);return req;}
        MockHttpServletResponse run(MockHttpServletRequest req)throws Exception{reached.set(false);var res=new MockHttpServletResponse();chain.doFilter(req,res,(r,s)->{reached.set(true);assertNotNull(TraceContext.REQUEST.get());});assertNull(TraceContext.REQUEST.get());assertNull(SecurityContextHolder.getContext().getAuthentication());assertNull(req.getSession(false));return res;}
        @Override public void close(){h.close();}
    }
    @AfterEach void clean(){TraceContext.REQUEST.remove();SecurityContextHolder.clearContext();RequestContextHolder.resetRequestAttributes();}
    @Test void configuredFiltersAreLocalSqlAndOrderedWithNoBasicFormOrCsrfFilters()throws Exception{try(var f=new Fixture()){var filters=f.h.context.getBean(SecurityFilterChain.class).getFilters();int trace=-1,host=-1,session=-1;for(int i=0;i<filters.size();i++){var filter=filters.get(i);if(filter instanceof TraceFilter){trace=i;assertSame(f.h.trace,field(filter,"store"));assertSame(f.h.context.getBean(Errors.class),field(filter,"errors"));assertNull(field(filter,"sql"));}if(filter instanceof HostFilter){host=i;assertSame(f.h.security,field(filter,"securityStore"));assertSame(f.h.settings,field(filter,"settings"));assertNull(field(filter,"sql"));}if(filter instanceof SessionFilter){session=i;assertSame(f.h.security,field(filter,"securityStore"));assertNull(field(filter,"sql"));}}assertTrue(trace>=0 && host>trace && session>host);assertTrue(filters.stream().noneMatch(filter->filter instanceof CsrfFilter || filter instanceof BasicAuthenticationFilter || filter instanceof UsernamePasswordAuthenticationFilter));assertTrue(f.h.context.getBeansOfType(TraceFilter.class).isEmpty());assertTrue(f.h.context.getBeansOfType(HostFilter.class).isEmpty());assertTrue(f.h.context.getBeansOfType(SessionFilter.class).isEmpty());assertEquals(1,f.h.context.getBeansOfType(SecurityFilterChain.class).size());verifyNoInteractions(f.h.security,f.h.trace);var e=assertThrows(UsernameNotFoundException.class,()->f.h.context.getBean(UserDetailsService.class).loadUserByUsername("synthetic@example.test"));assertEquals("Use the tenant session API",e.getMessage());}}
    @Test void exactPublicPatternsPermitAnonymousWhilePrivateAndPlatformRequireAuthentication()throws Exception{try(var f=new Fixture()){for(String path:List.of("/api/public/status","/api/public/synthetic","/api/auth/login","/api/auth/browser/login","/api/auth/invitations/accept","/api/auth/register","/api/auth/recovery/synthetic","/api/auth/verify/synthetic","/actuator/health/readiness")){var response=f.run(f.request("GET",path,"health.localhost"));assertEquals(200,response.getStatus(),path);assertTrue(f.reached.get(),path);}for(String path:List.of("/api/private","/api/platform/plans","/api/auth/browser/session","/actuator/info")){var response=f.run(f.request("GET",path,"health.localhost"));assertEquals(401,response.getStatus(),path);assertTrue(response.getContentAsString().contains("UNAUTHENTICATED"));assertFalse(f.reached.get());}verify(f.h.security,never()).resolveSession(any(),anyString());}}
    @Test void platformSadAllowedButSopDeniedAndSessionTenantCannotCrossHosts()throws Exception{try(var f=new Fixture()){for(String role:List.of("SAD","SOP")){f.session(null,role);var req=f.request("GET","/api/platform/plans","health.localhost");req.addHeader("Authorization","Bearer "+TOKEN);var response=f.run(req);assertEquals(role.equals("SAD")?200:403,response.getStatus());assertEquals(role.equals("SAD"),f.reached.get());}f.session(TENANT,null);var req=f.request("GET","/api/private","health.localhost");req.addHeader("Authorization","Bearer "+TOKEN);assertEquals(401,f.run(req).getStatus());assertFalse(f.reached.get());}}
    @Test void tenantBearerAndCookieCsrfPreserveSafeAndUnsafeMethodPolicies()throws Exception{try(var f=new Fixture()){f.session(TENANT,null);for(String method:List.of("GET","POST")){var req=f.request(method,"/api/private","clinic.health.localhost");req.setCookies(new Cookie("health_session",TOKEN));var response=f.run(req);assertEquals(method.equals("GET")?200:403,response.getStatus());if(method.equals("POST"))assertTrue(response.getContentAsString().contains("CSRF_INVALID"));}var cookie=f.request("POST","/api/private","clinic.health.localhost");cookie.setCookies(new Cookie("health_session",TOKEN));cookie.addHeader("X-CSRF-Token","synthetic-csrf");assertEquals(200,f.run(cookie).getStatus());var bearer=f.request("POST","/api/private","clinic.health.localhost");bearer.addHeader("Authorization","Bearer "+TOKEN);assertEquals(200,f.run(bearer).getStatus());verify(f.h.security,times(2)).applicationStatus(any());verify(f.h.security,times(3)).touchSession(any());}}
    @Test void originAndHostFailuresPrecedeSessionAndDoNotWidenPublicPaths()throws Exception{try(var f=new Fixture()){var rejected=f.request("POST","/api/auth/login","health.localhost");rejected.addHeader("Origin","http://other.invalid");assertEquals(403,f.run(rejected).getStatus());verifyNoInteractions(f.h.security);var accepted=f.request("POST","/api/auth/login","health.localhost");accepted.addHeader("Origin","http://health.localhost:8080");assertEquals(200,f.run(accepted).getStatus());assertTrue(f.reached.get());when(f.h.security.tenantBySlug(any(),eq("missing"))).thenReturn(Optional.empty());assertEquals(404,f.run(f.request("GET","/api/public/synthetic","missing.health.localhost")).getStatus());}}
    @Test void membershipApplicationGateAndBearerPrecedenceStillUseExistingRules()throws Exception{try(var f=new Fixture()){f.session(TENANT,null);when(f.h.security.activeMembership(any(),eq(ID))).thenReturn(Optional.empty());var denied=f.request("GET","/api/private","clinic.health.localhost");denied.addHeader("Authorization","Bearer "+TOKEN);assertEquals(401,f.run(denied).getStatus());f.session(TENANT,null);when(f.h.security.applicationStatus(any())).thenReturn(Map.of("mode","READ_ONLY","message","Synthetic"));var readonly=f.request("POST","/api/private","clinic.health.localhost");readonly.addHeader("Authorization","Bearer "+TOKEN);assertEquals(503,f.run(readonly).getStatus());var precedence=f.request("GET","/api/private","clinic.health.localhost");precedence.setCookies(new Cookie("health_session",TOKEN));precedence.addHeader("Authorization","Bearer invalid");assertEquals(401,f.run(precedence).getStatus());}}
    @Test void cleanupAndTraceStatusSurviveDownstreamExceptionWithoutHidingIt()throws Exception{try(var f=new Fixture()){f.session(TENANT,null);var req=f.request("GET","/api/private","clinic.health.localhost");req.addHeader("Authorization","Bearer "+TOKEN);var response=new MockHttpServletResponse();var failure=new ServletException("synthetic failure");assertSame(failure,assertThrows(ServletException.class,()->f.chain.doFilter(req,response,(r,s)->{throw failure;})));assertNull(TraceContext.REQUEST.get());assertNull(SecurityContextHolder.getContext().getAuthentication());verify(f.h.trace).finish(any(),anyString(),eq(500),anyLong());}}
}
